#include "usermodfx.h"
#include <stdint.h>
namespace{static constexpr uint32_t RNG_SEED=0x9e3779b9u;static float s1L=0,s2L=0,s1R=0,s2R=0,ct=.45f,dt=0,c=.45f,d=0;static uint32_t rng=RNG_SEED;static inline float c01(float x){return x<0?0:(x>1?1:x);}static inline float ca(float x){return x<-1?-1:(x>1?1:x);}static inline float cb(float x){return x<-3?-3:(x>3?3:x);}static inline uint32_t xr(){rng^=rng<<13;rng^=rng>>17;rng^=rng<<5;return rng;}static inline float sat(float x){float x2=x*x;return x*(27+x2)/(27+9*x2);}static float proc(float x,float&s1,float&s2,float coef,float dep){float noise=((int32_t)(xr()&65535)-32768)/32768.f;float g=coef*(1.f+.035f*dep*noise);float res=.15f+.78f*dep;float drive=1.f+3.f*dep;float u=sat((x-s2*res)*drive);s1=cb(s1+g*(u-s1));s2=cb(s2+g*(s1-s2));return ca(sat(s2*(1.f+.8f*dep)));}static void reset(){s1L=s2L=s1R=s2R=0;}}
void MODFX_INIT(uint32_t p,uint32_t a){(void)p;(void)a;ct=c=.45f;dt=d=0.f;rng=RNG_SEED;reset();}void MODFX_PROCESS(const float*x,float*y,const float*sx,float*sy,uint32_t n){(void)sx;(void)sy;for(uint32_t i=0;i<n;i++){c+=(ct-c)*.0015f;d+=(dt-d)*.0015f;float coef=.004f+.38f*c*c;y[2*i]=proc(x[2*i],s1L,s2L,coef,d);y[2*i+1]=proc(x[2*i+1],s1R,s2R,coef,d);}}
void MODFX_SUSPEND(){reset();}void MODFX_RESUME(){reset();}void MODFX_PARAM(uint8_t i,int32_t v){float n=c01(q31_to_f32(v));if(i==k_user_modfx_param_time)ct=n;else if(i==k_user_modfx_param_depth)dt=n;}
